import React, { useState, useEffect } from 'react';
import './App.css';
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min";

function App() {
  const [userName, setUserName] = useState("");
  const [pwd, setPwd] = useState("");
  const [value, setValue] = useState("");
  const [isLoginActive, setIsLoginActive] = useState(true); // State to toggle between login and register forms

  useEffect(() => {
    if (userName !== "" && pwd !== "" && userName === "admin" && pwd === "admin123") {
      setValue(true);
    } else {
      setValue(false);
    }
  }, [userName, pwd]); // UseEffect Dependency

  const update = (e) => {
    e.preventDefault(); // Prevent default form submission behavior
    if (value) {
      alert("Login Success");
    } else {
      alert("Login Failed");
    }
  };

  const toggleForms = (formType) => {
    if (formType === "login") {
      setIsLoginActive(true);
    } else {
      setIsLoginActive(false);
    }
  };

  return (
    <div className='parent_container'>
    <div className={`form-container ${isLoginActive ? "" : "register-active"}`}>
      <div className="col col-2">
        <div className="btn-box">
          <button
            className="btn btn-1"
            id="login"
            onClick={() => toggleForms('login')}
          >
            Sign In
          </button>
          <button
            className="btn btn-2"
            id="register"
            onClick={() => toggleForms('register')}
          >
            Sign Up
          </button>
        </div>
      </div>
      <div className="container">
        <form onSubmit={update}>
          {/* Login Form container */}
          {isLoginActive ? (
            <div className="login-form">
              <div className="form-title">
                <span>Sign In</span>
              </div>
              <div className="form-inputs">
                <div className="input-box">
                  <input
                    type="text"
                    className="input-field"
                    onChange={(e) => setUserName(e.target.value)}
                    placeholder="Username"
                    required
                  />
                  <i className="bx bx-user-alt icon"></i>
                </div>
                <div className="input-box">
                  <input
                    type="password"
                    className="input-field"
                    onChange={(e) => setPwd(e.target.value)}
                    placeholder="Password"
                    required
                  />
                  <i className="bx bx-lock-alt icon"></i>
                </div>
                <div className="forget-pass">
                  <a href="/recover-password">Forget Password</a>
                </div>
                <div className="input-box">
                  <button className="input-submit">
                    <span>Sign In</span>
                    <i className="bx bx-right-arrow-alt"></i>
                  </button>
                </div>
              </div>
            </div>
          ) : (
            // Register Form container
            <div className="register-form">
              <div className="form-title">
                <span>Create Account</span>
              </div>
              <div className="form-inputs">
                <div className="input-box">
                  <input
                    type="email"
                    className="input-field"
                    placeholder="Email"
                    required
                  />
                  <i className="bx bx-envelope-alt icon"></i>
                </div>
                <div className="input-box">
                  <input
                    type="text"
                    className="input-field"
                    placeholder="Username"
                    required
                  />
                  <i className="bx bx-user-alt icon"></i>
                </div>
                <div className="input-box">
                  <input
                    type="password"
                    className="input-field"
                    placeholder="Password"
                    required
                  />
                  <i className="bx bx-lock-alt icon"></i>
                </div>
                <div className="input-box">
                  <button className="input-submit">
                    <span>Sign Up</span>
                    <i className="bx bx-right-arrow-alt"></i>
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* Submit button */}
          <input type="submit" style={{ display: 'none' }} />
        </form>
      </div>
    </div>
    </div>
  );
}

export default App;
